begin;
create table public.dynamo_ticket_numbers(number text primary key);
alter table public.dynamo_ticket_numbers enable row level security;
revoke all on public.dynamo_ticket_numbers from public,anon,authenticated;
grant select,insert on public.dynamo_ticket_numbers to service_role;
create function public.next_dynamo_ticket() returns text language plpgsql security invoker set search_path='' as $$declare code text;begin loop code:='DYN-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4));insert into public.dynamo_ticket_numbers values(code) on conflict do nothing;if found then return code;end if;end loop;end $$;
revoke all on function public.next_dynamo_ticket() from public,anon,authenticated;
grant execute on function public.next_dynamo_ticket() to service_role;
alter table public.dynamo_event_bookings add column ticket_number text not null default public.next_dynamo_ticket();
alter table public.dynamo_party_bookings add column ticket_number text not null default public.next_dynamo_ticket();
create unique index dynamo_event_ticket_number on public.dynamo_event_bookings(ticket_number);
create unique index dynamo_party_ticket_number on public.dynamo_party_bookings(ticket_number);
create table public.dynamo_confirmation_settings(kind text primary key check(kind in ('event','party')),details jsonb not null);
alter table public.dynamo_confirmation_settings enable row level security;
revoke all on public.dynamo_confirmation_settings from public,anon,authenticated;
grant select,update on public.dynamo_confirmation_settings to service_role;
insert into public.dynamo_confirmation_settings values('event','{"enabled":true,"qrEnabled":false,"subject":"Your Dynamo event booking confirmation","greeting":"Hi {parentName},","intro":"Thank you for booking with Dynamo Gymnastics. Your confirmed tickets are below.","instructions":"Please keep this confirmation for your visit."}'),('party','{"enabled":true,"qrEnabled":false,"subject":"Your Dynamo birthday party confirmation","greeting":"Hi {parentName},","intro":"Thank you for booking your birthday party with Dynamo Gymnastics. Your confirmed party details are below.","instructions":"We look forward to celebrating with you!"}');
create table public.dynamo_confirmation_jobs(id uuid primary key references public.dynamo_basket_checkouts(id),account_id uuid not null references public.dynamo_accounts(id),booking_ids uuid[] not null,status text not null default 'pending' check(status in ('pending','sending','sent','review','skipped')),error_code text,created_at timestamptz not null default now(),sent_at timestamptz,attempted_at timestamptz);
create index dynamo_confirmation_account on public.dynamo_confirmation_jobs(account_id);
create index dynamo_confirmation_pending on public.dynamo_confirmation_jobs(status,created_at);
alter table public.dynamo_confirmation_jobs enable row level security;
revoke all on public.dynamo_confirmation_jobs from public,anon,authenticated;
grant select,insert,update on public.dynamo_confirmation_jobs to service_role;
do $$declare def text;begin select pg_get_functiondef(oid) into def from pg_proc where proname='checkout_dynamo_basket';def:=replace(def,'values(p_operation,p_account,p_items,result);return result;','values(p_operation,p_account,p_items,result);insert into public.dynamo_confirmation_jobs(id,account_id,booking_ids) values(p_operation,p_account,array(select (v->>''bookingId'')::uuid from jsonb_array_elements(results) v));return result;');if position('insert into public.dynamo_confirmation_jobs' in def)=0 then raise exception 'Checkout queue patch failed';end if;execute def;end $$;
commit;
